-- FRM-902 — frm902 sanitation verification log.
--
-- Give FRM-902 (Sanitation Verification Log) its fillable schema: one record per verification session,
-- a results grid of ATP/micro/allergen/visual swabs vs. limit (SQF 11.2.5.9). Previously empty.
--
-- Deployed as status=draft for in-app review before activation (the project workflow). The
-- sop_documents_history trigger fires here because the row is currently active and form_schema is a
-- watched field, so the prior schema is snapshotted (existing draft test entries keep rendering via
-- the revision-matched snapshot; revision is bumped where entries exist). Idempotent on sop_number.

update public.sop_documents set
  status = 'draft',
  content = coalesce(content, '{}'::jsonb) || jsonb_build_object('form_schema', $json${"sections":[{"id":"purpose","title":"Purpose & Scope","fields":[{"id":"purpose_info","type":"info","label":"Purpose & Scope","text":"Documents verification that cleaning and sanitation achieve the required standard \u2014 beyond routine pre-operational inspection (FRM-903) \u2014 using ATP, microbiological or allergen swabs and visual checks (SQF 11.2.5.1 (v)(vii), 11.2.5.9). Record each result against its acceptable limit; on a Fail, re-clean, re-test, and record the outcome. Records are maintained for a minimum of 12 months (SOP-11.2.12; SQF 11.2.5.9)."}]},{"id":"details","title":"Verification Session","fields":[{"id":"verification_date","type":"date","label":"Date","width":"third","required":true,"showInList":true,"defaultToday":true},{"id":"performed_by","type":"text","label":"Performed by","width":"third","showInList":true}]},{"id":"schedule","title":"Verification Schedule (reference)","description":"The surfaces verified, the method, the frequency, and the acceptable limit (SQF 11.2.5.9). Reference only \u2014 record actual results below.","fields":[{"id":"schedule_ref","type":"reference_table","label":"Verification schedule","columns":["Area / Surface","Method","Frequency","Acceptable limit / standard"],"rows":[["Mixer food-contact surface","ATP swab","Weekly","< 10 RLU / pass"],["Depositor food-contact surface","ATP swab","Weekly","< 10 RLU / pass"],["Kettle food-contact surface","ATP swab","Weekly","< 10 RLU / pass"],["Allergen changeover surface","Allergen swab","At changeover","Negative"]]}]},{"id":"results","title":"Verification Results","description":"Record each verification result against its limit. On a Fail, re-clean, re-test, and record the re-test result. Add a row per surface tested.","fields":[{"id":"swabs","type":"grid","label":"Results","rows":{"mode":"dynamic","addLabel":"Add result"},"columns":[{"id":"area_surface","type":"text","label":"Area / surface tested","width":3,"required":true},{"id":"method","type":"select","label":"Method","width":2,"options":["ATP swab","Microbiological swab","Allergen swab","Visual"],"required":true},{"id":"result_reading","type":"text","label":"Result / reading","width":2},{"id":"accept_limit","type":"text","label":"Acceptable limit","width":2},{"id":"pass_fail","type":"pass_fail","label":"Pass / fail","width":1,"required":true},{"id":"corrective_action","type":"text","label":"Corrective action","width":3},{"id":"retest_result","type":"text","label":"Re-test result","width":2},{"id":"verified_by","type":"text","label":"Verified by","width":2}]}]},{"id":"review","title":"Review","fields":[{"id":"reviewed_by","type":"signature","role":"verifier","label":"Reviewed by (SQF Practitioner)","width":"half","statement":"I reviewed these verification results for trends and program effectiveness."},{"id":"review_date","type":"date","label":"Date","width":"half"}]}],"settings":{"deletable":false,"attachmentsEnabled":true,"allowMultipleDrafts":true,"requireVerification":false,"instanceTitleTemplate":"{verification_date} \u2014 Sanitation verification"},"schemaVersion":1}$json$::jsonb)
where sop_number = 'FRM-902';

insert into supabase_migrations.schema_migrations (version, name)
values ('20260727000002', 'frm902_sanitation_verification_log')
on conflict (version) do nothing;
